function AO_Frame(key)
    do return LoadFrameHandle(AO_Frames, 0, key) end
end

function AO_Register(tid, label, art, model, category, dps, ground, air)
    AO_Types[AO_TypeCount] = tid
    AO_TypeCount = J88_int(AO_TypeCount + 1)
    SaveStr(AO_Data, tid, 0, label)
    SaveStr(AO_Data, tid, 1, art)
    SaveStr(AO_Data, tid, 2, model)
    SaveInteger(AO_Data, tid, 6, category)
    SaveReal(AO_Data, tid, 3, dps)
    SaveReal(AO_Data, tid, 4, ground)
    SaveReal(AO_Data, tid, 5, air)
end

