function AO_Add(tid, count)
    --  Local presentation data lives in a Lua table; game hashtables are never written locally.
    AO_Count[tid] = J88_int((AO_Count[tid] or 0) + count)
end

function AO_Building(tid)
    local i = 0
    local count = 0
    tid = Mao_CanonicalType(tid)
    if (((((tid == 1750675762) or (tid == 1749437744)) or (tid == 1749435952)) or (tid == CT_T59)) and (not RoundSchedule_IsFinalRound(udg_int_CurRound))) then
        do return end
    end
    count = LoadInteger(AO_Data, tid, 20)
    while true do
        if (i >= count) then break end
        AO_Add(LoadInteger(AO_Data, tid, J88_int(100 + i)), LoadInteger(AO_Data, tid, J88_int(200 + i)))
        i = J88_int(i + 1)
    end
end

function AO_Collect(owner)
    local i = 0
    local tid = 0
    local count = 0
    local category = 0
    local u = nil
    --  Clear entries under the reusable parent key, never destroy the table.
    AO_Count = {}
    for _, owned in ipairs(UI76_Owned[GetPlayerId(owner)] or {}) do
        u = owned
        if (GetWidgetLife(u) > 0.4050000011920929) then
            AO_Building(GetUnitTypeId(u))
        end
    end
    AO_VisibleCount = 0
    AO_Total = 0
    AO_DPS = 0.0
    AO_Ground = 0.0
    AO_Air = 0.0
    while true do
        if (i >= 5) then break end
        AO_Categories[i] = 0
        i = J88_int(i + 1)
    end
    i = 0
    while true do
        if (i >= AO_TypeCount) then break end
        tid = AO_Types[i]
        count = (AO_Count[tid] or 0)
        if (count > 0) then
            AO_Visible[AO_VisibleCount] = tid
            AO_VisibleCount = J88_int(AO_VisibleCount + 1)
            AO_Total = J88_int(AO_Total + count)
            category = LoadInteger(AO_Data, tid, 6)
            AO_Categories[category] = J88_int(AO_Categories[category] + count)
            AO_DPS = J88_real(AO_DPS + J88_real(LoadReal(AO_Data, tid, 3) * I2R(count)))
            AO_Ground = J88_real(AO_Ground + J88_real(LoadReal(AO_Data, tid, 4) * I2R(count)))
            AO_Air = J88_real(AO_Air + J88_real(LoadReal(AO_Data, tid, 5) * I2R(count)))
        end
        i = J88_int(i + 1)
    end
    --  An empty army receives the same fallback soldier as CreateSpawnArray.
    if ((AO_Total == 0) and (not udg_bool_InFinalRound)) then
        AO_Add(1747988534, 1)
        AO_Visible[0] = 1747988534
        AO_VisibleCount = 1
        AO_Total = 1
        AO_Categories[LoadInteger(AO_Data, 1747988534, 6)] = 1
        AO_DPS = LoadReal(AO_Data, 1747988534, 3)
        AO_Ground = LoadReal(AO_Data, 1747988534, 4)
        AO_Air = LoadReal(AO_Data, 1747988534, 5)
    end
    u = nil
end

function AO_Render()
    local i = 0
    local index = 0
    local tid = 0
    local count = 0
    local key = 0
    local pages = IMaxBJ(1, J88_div(J88_int(J88_int(AO_VisibleCount + AO_PageSize) - 1), AO_PageSize))
    AO_Page = IMinBJ(AO_Page, J88_int(pages - 1))
    BlzFrameSetText(AO_Frame(2), J88_concat("|cffffd36bArmy Overview|r  |  ", GetPlayerName(GetLocalPlayer())))
    BlzFrameSetText(AO_Frame(3), J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat("Per wave: |cffffffff", I2S(AO_Total)), "|r    Base DPS: |cffffd36b"), R2SW(AO_DPS, 1, 1)), "|r|nGround DPS: "), R2SW(AO_Ground, 1, 1)), "    Air DPS: "), R2SW(AO_Air, 1, 1)))
    BlzFrameSetText(AO_Frame(4), J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat("Infantry: ", I2S(AO_Categories[0])), "    Light vehicles: "), I2S(AO_Categories[1])), "|nHeavy vehicles: "), I2S(AO_Categories[2])), "    Aircraft: "), I2S(AO_Categories[3])), "    Fortifications: "), I2S(AO_Categories[4])))
    BlzFrameSetText(AO_Frame(9), J88_concat(J88_concat(I2S(J88_int(AO_Page + 1)), " / "), I2S(pages)))
    BlzFrameSetEnable(AO_Frame(7), (AO_Page > 0))
    BlzFrameSetEnable(AO_Frame(8), (J88_int(AO_Page + 1) < pages))
    while true do
        if (i >= 9) then break end
        key = J88_int(20 + J88_int(i * 5))
        index = J88_int(J88_int(AO_Page * AO_PageSize) + i)
        if ((i < AO_PageSize) and (index < AO_VisibleCount)) then
            tid = AO_Visible[index]
            count = (AO_Count[tid] or 0)
            BlzFrameSetVisible(AO_Frame(key), true)
            BlzFrameSetTexture(AO_Frame(J88_int(key + 1)), LoadStr(AO_Data, tid, 1), 0, true)
            BlzFrameSetText(AO_Frame(J88_int(key + 2)), J88_concat(J88_concat(J88_concat(LoadStr(AO_Data, tid, 0), " |cffffd36bx "), I2S(count)), "|r"))
            BlzFrameSetText(AO_Frame(J88_int(key + 3)), J88_concat(J88_concat(J88_concat(J88_concat(J88_concat("DPS ", R2SW(J88_real(LoadReal(AO_Data, tid, 3) * I2R(count)), 1, 1)), "|nGround "), R2SW(J88_real(LoadReal(AO_Data, tid, 4) * I2R(count)), 1, 1)), " | Air "), R2SW(J88_real(LoadReal(AO_Data, tid, 5) * I2R(count)), 1, 1)))
        else
            BlzFrameSetVisible(AO_Frame(key), false)
        end
        i = J88_int(i + 1)
    end
end

function AO_Refresh()
    --  Synchronized timer: list every player's units on every client, then draw locally.
    UI76_SyncLists(UI76_Owned, false)
    AO_RefreshLocal()
end

function AO_RefreshLocal()
    local pid = GetPlayerId(GetLocalPlayer())
    if (((not AO_Open) or (pid < 0)) or (pid >= 8)) then
        do return end
    end
    --  Existing group and hashtables only. No units, handles or orders are created locally.
    AO_Collect(GetLocalPlayer())
    AO_Render()
end

function AO_Layout()
    local x = 0.019999999552965164
    local width = 0.49000000953674316
    local cardWidth = 0.23100000619888306
    local columns = 2
    local i = 0
    local key = 0
    local cx = 0.0
    local cy = 0.0
    if AO_Large then
        width = 0.7599999904632568
        columns = 3
        cardWidth = 0.24400000274181366
        AO_PageSize = 9
    else
        AO_PageSize = 6
    end
    UI5_Box(AO_Frame(1), x, 0.19599999487400055, width, 0.36500000953674316)
    UI5_Box(AO_Frame(2), J88_real(x + 0.012000000104308128), 0.5299999713897705, J88_real(width - 0.18000000715255737), 0.02199999988079071)
    UI5_Box(AO_Frame(5), J88_real(J88_real(x + width) - 0.1589999943971634), 0.5299999713897705, 0.07400000095367432, 0.023000000044703484)
    UI5_Box(AO_Frame(6), J88_real(J88_real(x + width) - 0.0820000022649765), 0.5299999713897705, 0.0689999982714653, 0.023000000044703484)
    UI5_Box(AO_Frame(3), J88_real(x + 0.012000000104308128), 0.4950000047683716, J88_real(width - 0.024000000208616257), 0.032999999821186066)
    UI5_Box(AO_Frame(4), J88_real(x + 0.012000000104308128), 0.46299999952316284, J88_real(width - 0.024000000208616257), 0.03200000151991844)
    UI5_Box(AO_Frame(10), J88_real(x + 0.012000000104308128), 0.20399999618530273, J88_real(width - 0.2150000035762787), 0.02500000037252903)
    UI5_Box(AO_Frame(11), J88_real(x + 0.012000000104308128), 0.4449999928474426, J88_real(width - 0.024000000208616257), 0.019999999552965164)
    UI5_Box(AO_Frame(7), J88_real(J88_real(x + width) - 0.12999999523162842), 0.2029999941587448, 0.03500000014901161, 0.02500000037252903)
    UI5_Box(AO_Frame(9), J88_real(J88_real(x + width) - 0.09300000220537186), 0.2029999941587448, 0.04100000113248825, 0.02500000037252903)
    UI5_Box(AO_Frame(8), J88_real(J88_real(x + width) - 0.04899999871850014), 0.2029999941587448, 0.03500000014901161, 0.02500000037252903)
    while true do
        if (i >= 9) then break end
        key = J88_int(20 + J88_int(i * 5))
        cx = J88_real(J88_real(x + 0.010999999940395355) + J88_real(I2R(ModuloInteger(i, columns)) * J88_real(cardWidth + 0.006000000052154064)))
        cy = J88_real(0.3700000047683716 - J88_real(I2R(J88_div(i, columns)) * 0.0689999982714653))
        UI5_Box(AO_Frame(key), cx, cy, cardWidth, 0.06599999964237213)
        UI5_Box(AO_Frame(J88_int(key + 1)), J88_real(cx + 0.003000000026077032), J88_real(cy + 0.00800000037997961), 0.05000000074505806, 0.05000000074505806)
        UI5_Box(AO_Frame(J88_int(key + 2)), J88_real(cx + 0.057999998331069946), J88_real(cy + 0.03500000014901161), J88_real(cardWidth - 0.061000000685453415), 0.028999999165534973)
        UI5_Box(AO_Frame(J88_int(key + 3)), J88_real(cx + 0.057999998331069946), J88_real(cy + 0.004999999888241291), J88_real(cardWidth - 0.061000000685453415), 0.02800000086426735)
        i = J88_int(i + 1)
    end
    if AO_Large then
        BlzFrameSetText(AO_Frame(5), "Compact")
    else
        BlzFrameSetText(AO_Frame(5), "Enlarge")
    end
end

function AO_Click()
    local clicked = BlzGetTriggerFrame()
    if (GetTriggerPlayer() == GetLocalPlayer()) then
        if (clicked == AO_Frame(0)) then
            AO_Open = (not AO_Open)
        elseif (clicked == AO_Frame(6)) then
            AO_Open = false
        elseif (clicked == AO_Frame(5)) then
            AO_Large = (not AO_Large)
            AO_Page = 0
            AO_Layout()
        elseif (clicked == AO_Frame(7)) then
            AO_Page = IMaxBJ(0, J88_int(AO_Page - 1))
        elseif (clicked == AO_Frame(8)) then
            AO_Page = J88_int(AO_Page + 1)
        end
        --  Clear button focus so hotkeys return to normal game input.
        BlzFrameSetEnable(clicked, false)
        BlzFrameSetEnable(clicked, true)
        BlzFrameSetVisible(AO_Frame(1), AO_Open)
        if AO_Open then
            PM69_Activate(2)
        end
        AO_RefreshLocal()
    end
    clicked = nil
end

function AO_Text(key, parent, size)
    SaveFrameHandle(AO_Frames, 0, key, BlzCreateFrameByType("TEXT", "ArmyOverviewText", parent, "", key))
    BlzFrameSetFont(AO_Frame(key), "Fonts\\FRIZQT__.TTF", size, 0)
    BlzFrameSetTextAlignment(AO_Frame(key), TEXT_JUSTIFY_MIDDLE, TEXT_JUSTIFY_LEFT)
    BlzFrameSetTextColor(AO_Frame(key), BlzConvertColor(255, 216, 225, 207))
end

function AO_Button(key, parent, label)
    SaveFrameHandle(AO_Frames, 0, key, BlzCreateFrame("ScriptDialogButton", parent, 0, key))
    BlzFrameSetText(AO_Frame(key), label)
    BlzTriggerRegisterFrameEvent(AO_ClickTrigger, AO_Frame(key), FRAMEEVENT_CONTROL_CLICK)
end

function AO_Init()
    local i = 0
    local key = 0
    local root = BlzGetOriginFrame(ORIGIN_FRAME_GAME_UI, 0)
    --  Allocate identically on every client. Later changes affect local presentation only.
    AO_Frames = InitHashtable()
    AO_Data = InitHashtable()
    AO_Count = {}
    AO_Scan = CreateGroup()
    AO_Timer = CreateTimer()
    AO_ClickTrigger = CreateTrigger()
    TriggerAddAction(AO_ClickTrigger, AO_Click)
    AO_LoadData()
    US95_RegisterOverview()
    Mac70_RegisterOverview()
    AO_Button(0, root, "Army Overview")
    UI5_Box(AO_Frame(0), J88_real(UI70_Left() + 0.10300000011920929), 0.5659999847412109, 0.10499999672174454, 0.024000000208616257)
    BlzFrameSetVisible(AO_Frame(0), (GetPlayerId(GetLocalPlayer()) < 8))
    SaveFrameHandle(AO_Frames, 0, 1, BlzCreateFrameByType("BACKDROP", "ArmyOverview", root, "", 0))
    BlzFrameSetTexture(AO_Frame(1), "UI\\WW2HUD\\panel.blp", 0, true)
    BlzFrameSetLevel(AO_Frame(1), 8)
    AO_Text(2, AO_Frame(1), 0.012000000104308128)
    AO_Text(3, AO_Frame(1), 0.009999999776482582)
    AO_Text(4, AO_Frame(1), 0.010999999940395355)
    AO_Text(9, AO_Frame(1), 0.009999999776482582)
    AO_Text(10, AO_Frame(1), 0.008999999612569809)
    AO_Text(11, AO_Frame(1), 0.008999999612569809)
    BlzFrameSetText(AO_Frame(10), "From your buildings. Infantry includes cavalry.")
    BlzFrameSetText(AO_Frame(11), "Base DPS before armor and bonuses. Fortresses assume 4 targets.")
    AO_Button(5, AO_Frame(1), "Enlarge")
    AO_Button(6, AO_Frame(1), "Minimize")
    AO_Button(7, AO_Frame(1), "<")
    AO_Button(8, AO_Frame(1), ">")
    while true do
        if (i >= 9) then break end
        key = J88_int(20 + J88_int(i * 5))
        SaveFrameHandle(AO_Frames, 0, key, BlzCreateFrameByType("BACKDROP", "ArmyOverviewCard", AO_Frame(1), "", i))
        BlzFrameSetTexture(AO_Frame(key), "UI\\WW2HUD\\panel.blp", 0, true)
        SaveFrameHandle(AO_Frames, 0, J88_int(key + 1), BlzCreateFrameByType("BACKDROP", "ArmyOverviewIcon", AO_Frame(key), "", i))
        AO_Text(J88_int(key + 2), AO_Frame(key), 0.009999999776482582)
        AO_Text(J88_int(key + 3), AO_Frame(key), 0.008999999612569809)
        i = J88_int(i + 1)
    end
    AO_Layout()
    BlzFrameSetVisible(AO_Frame(1), false)
    TimerStart(AO_Timer, 0.5, true, AO_Refresh)
    root = nil
end
